      "    if (res.status !== 200) { toast(`${action.label}失败：${errText(res)}`, 'bad'); return }",
      "    toast(`${action.label}完成`, 'ok')",
      "    void load()",
      "  }",
      "",
      "  return { node: card, load, get rows() { return state.rows } }",
      "}",
